import{_ as a,o as t,c as o,ag as s}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"Records as DTOs — Coding Exercises","description":"","frontmatter":{},"headers":[],"relativePath":"java/coding_fluency/records/Records.md","filePath":"java/coding_fluency/records/Records.md"}'),i={name:"java/coding_fluency/records/Records.md"};function n(r,e,c,d,l,h){return t(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="records-as-dtos-—-coding-exercises" tabindex="-1">Records as DTOs — Coding Exercises <a class="header-anchor" href="#records-as-dtos-—-coding-exercises" aria-label="Permalink to &quot;Records as DTOs — Coding Exercises&quot;">​</a></h1><h2 id="why-this-matters" tabindex="-1">Why this matters <a class="header-anchor" href="#why-this-matters" aria-label="Permalink to &quot;Why this matters&quot;">​</a></h2><p>Records (Java 16+) are the language-native immutable data carrier. They eliminate the boilerplate of a Lombok <code>@Value</code> class with zero annotation-processing dependencies. On a KYC platform, API response bodies and event payloads are natural candidates — created once, read many times, never mutated. Knowing where records stop and where Lombok picks up (toBuilder, Jackson quirks, inheritance limits) determines when to reach for which tool.</p><h2 id="domain-model" tabindex="-1">Domain model <a class="header-anchor" href="#domain-model" aria-label="Permalink to &quot;Domain model&quot;">​</a></h2><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> java.math.BigDecimal;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// You will define this as a record and experiment with its constraints.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Records are implicitly final — they cannot be subclassed.</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">record</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> TransactionDto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    String id,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    BigDecimal amount,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    String currency   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ISO-4217, e.g. &quot;USD&quot;, &quot;IDR&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// A user identity snapshot used in KYC checks</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">record</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> KycSubjectDto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    String userId,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    String fullName,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    String nationalId</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {}</span></span></code></pre></div><h2 id="exercise-1-basic-record-dto-jackson-round-trip-10-min" tabindex="-1">Exercise 1: Basic record DTO + Jackson round-trip (~10 min) <a class="header-anchor" href="#exercise-1-basic-record-dto-jackson-round-trip-10-min" aria-label="Permalink to &quot;Exercise 1: Basic record DTO + Jackson round-trip (~10 min)&quot;">​</a></h2><p><strong>Goal:</strong> Define <code>TransactionDto</code> as a record and verify its automatically generated contract.</p><p><strong>Task:</strong></p><ol><li>Declare the record. Create two instances with the same data. Confirm <code>equals()</code> returns <code>true</code> without writing a single method.</li><li>Call <code>toString()</code> on an instance — note the format.</li><li>Try to assign to a field (<code>dto.amount = new BigDecimal(&quot;200&quot;)</code>) — what does the compiler say?</li><li>Serialize <code>TransactionDto</code> to JSON using Jackson&#39;s <code>ObjectMapper</code>. Then deserialize it back. If deserialization fails, diagnose the error message and apply the minimal fix.</li></ol><p><strong>Gotcha:</strong> Jackson 2.11 and earlier cannot map JSON keys to record constructor parameters by name without the <code>jackson-module-parameter-names</code> module or a <code>@JsonCreator</code>-annotated constructor. Jackson 2.12+ (Spring Boot 2.7+) handles records out of the box — check your version before adding anything.</p><hr><h2 id="exercise-2-compact-constructor-validation-10-min" tabindex="-1">Exercise 2: Compact constructor validation (~10 min) <a class="header-anchor" href="#exercise-2-compact-constructor-validation-10-min" aria-label="Permalink to &quot;Exercise 2: Compact constructor validation (~10 min)&quot;">​</a></h2><p><strong>Goal:</strong> Add input validation inside the compact constructor — the idiomatic record replacement for a factory method or builder validation step.</p><p><strong>Task:</strong><br> Add a compact constructor to <code>TransactionDto</code> that:</p><ol><li>Throws <code>IllegalArgumentException</code> if <code>amount</code> is null or not positive (≤ 0).</li><li>Throws <code>IllegalArgumentException</code> if <code>currency</code> is not exactly 3 uppercase letters (hint: <code>currency.matches(&quot;[A-Z]{3}&quot;</code>)).</li></ol><p>Write a main method that:</p><ul><li>Creates a valid <code>TransactionDto</code> — should succeed.</li><li>Attempts <code>amount = BigDecimal.ZERO</code> — should throw.</li><li>Attempts <code>currency = &quot;usd&quot;</code> — should throw.</li></ul><p><strong>Gotcha:</strong> The compact constructor does NOT redeclare parameters — write <code>TransactionDto { ... }</code> with no parameter list. To normalise a value (e.g., strip whitespace), assign to the <em>parameter name</em> directly, NOT to <code>this.field</code>:</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TransactionDto {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    currency </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> currency.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toUpperCase</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// assigns to the parameter; this.currency is set implicitly after the body</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>this.currency = ...</code> inside a compact constructor is a compile error. In this exercise you only validate, not normalize.</p><hr><h2 id="exercise-3-records-vs-lombok-value-—-side-by-side-15-min" tabindex="-1">Exercise 3: Records vs Lombok @Value — side-by-side (~15 min) <a class="header-anchor" href="#exercise-3-records-vs-lombok-value-—-side-by-side-15-min" aria-label="Permalink to &quot;Exercise 3: Records vs Lombok @Value — side-by-side (~15 min)&quot;">​</a></h2><p><strong>Goal:</strong> Build the same DTO twice and compare the two approaches on verbosity, flexibility, and Jackson compatibility.</p><p><strong>Task:</strong><br> Create <code>KycSubjectDto</code> as:</p><ul><li>A <code>record</code> (one declaration line + compact constructor if you add validation).</li><li>A Lombok <code>@Value</code> class with the same three fields.</li></ul><p>For each, answer:</p><table tabindex="0"><thead><tr><th>Question</th><th>record</th><th>@Value</th></tr></thead><tbody><tr><td>Lines of code (no validation)</td><td></td><td></td></tr><tr><td>Immutable by language guarantee?</td><td></td><td></td></tr><tr><td>Supports inheritance (extend a class)?</td><td></td><td></td></tr><tr><td>Jackson deserialization works out of box?</td><td></td><td></td></tr><tr><td>Can add mutable state?</td><td></td><td></td></tr><tr><td>toBuilder() available?</td><td></td><td></td></tr></tbody></table><p><strong>Gotcha:</strong> Records implicitly extend <code>java.lang.Record</code> and cannot extend any other class. Lombok <code>@Value</code> classes extend nothing by default. Both can implement interfaces; only Lombok lets you extend a superclass.</p><hr><h2 id="exercise-4-simulating-tobuilder-on-records-10-min" tabindex="-1">Exercise 4: Simulating toBuilder() on records (~10 min) <a class="header-anchor" href="#exercise-4-simulating-tobuilder-on-records-10-min" aria-label="Permalink to &quot;Exercise 4: Simulating toBuilder() on records (~10 min)&quot;">​</a></h2><p><strong>Goal:</strong> Understand that records have no built-in copy-with-modification support, and write the manual workaround.</p><p><strong>Task:</strong><br> Records have no <code>toBuilder()</code>. Simulate it by writing a <code>withAmount(BigDecimal newAmount)</code> instance method on <code>TransactionDto</code> that returns a new <code>TransactionDto</code> with the same <code>id</code> and <code>currency</code> but the new amount.</p><p>Write the method, create a base transaction, derive a modified copy, and confirm:</p><ul><li>The original is unchanged.</li><li>The new object has the updated amount.</li><li><code>equals()</code> returns <code>false</code> between the two (different amounts).</li></ul><p>Then write a <code>withCurrency(String newCurrency)</code> method the same way. Now imagine this record had 10 fields — write out in a comment what the <code>withX</code> method for field 7 would look like, and note how unpleasant it is compared to Lombok&#39;s <code>toBuilder()</code>.</p><p><strong>Gotcha:</strong> There is no language shortcut. Each <code>withX</code> method must name every other field explicitly. This verbosity is the main reason to prefer Lombok <code>@Value</code> + <code>@Builder(toBuilder = true)</code> for DTOs that need frequent partial-copy patterns (e.g., updating status fields in a pipeline).</p><hr><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q.</strong> What methods does a record auto-generate?<br><strong>A.</strong> A public all-args canonical constructor, a getter for each component (named after the field, not <code>getX</code>), <code>equals()</code>, <code>hashCode()</code>, and <code>toString()</code>.</p><p><strong>Q.</strong> What is a compact constructor and where does it live?<br><strong>A.</strong> A constructor body written as <code>RecordName { ... }</code> with no parameter list — it runs before the canonical constructor assigns fields, used for validation or normalization.</p><p><strong>Q.</strong> Are records final? Can they be subclassed?<br><strong>A.</strong> Yes, records are implicitly <code>final</code>. They cannot be extended by any class.</p><p><strong>Q.</strong> Why can a record not extend another class?<br><strong>A.</strong> Records implicitly extend <code>java.lang.Record</code>, and Java does not support multiple inheritance of classes. They can, however, implement any number of interfaces.</p><p><strong>Q.</strong> What is the minimal Jackson fix when record deserialization fails?<br><strong>A.</strong> On Spring Boot 2.7+ / Jackson 2.12+ no fix is needed — built-in record support is included. On older versions, add <code>jackson-module-parameter-names</code> with <code>-parameters</code> compiler flag, or annotate the canonical constructor with <code>@JsonCreator</code> + <code>@JsonProperty</code>.</p><p><strong>Q.</strong> When should you prefer Lombok <code>@Value</code> + <code>@Builder</code> over a record?<br><strong>A.</strong> When you need frequent partial-copy patterns (<code>toBuilder()</code>), Jackson deserialization without extra config, or you are on Java &lt; 16. Prefer records for simplicity when the DTO is small, immutable, and Jackson config is already in place.</p>`,44)])])}const m=a(i,[["render",n]]);export{u as __pageData,m as default};
